changeSet.sql:
CREATE TABLE public.mentor_source ( id UUID NOT NULL CONSTRAINT mentor_sourcePK PRIMARY KEY, account_id BIGINT NOT NULL, binding_id BIGINT NOT NULL, workspace_id BIGINT NOT NULL, container_id VARCHAR(255) NOT NULL, native_message_id VARCHAR(255) NOT NULL, producer VARCHAR(16) NOT NULL, revision VARCHAR(64) NOT NULL, state VARCHAR(16) NOT NULL, CONSTRAINT uk_mentor_source_message UNIQUE (binding_id, container_id, native_message_id), -- A foreign key ignores row-level security, so a reference names the owner too. CONSTRAINT uk_mentor_source_owner UNIQUE (account_id, id), CONSTRAINT ck_mentor_source_producer CHECK (producer IN ('LEGACY', 'MENTOR')), CONSTRAINT ck_mentor_source_state CHECK (state IN ('LIVE', 'DELETED')) ); CREATE INDEX idx_mentor_source_workspace ON public.mentor_source (workspace_id); CREATE TABLE public.mentor_request ( id UUID NOT NULL CONSTRAINT mentor_requestPK PRIMARY KEY, account_id BIGINT NOT NULL, source_id UUID NOT NULL, version INTEGER NOT NULL, state VARCHAR(16) NOT NULL, audience_transport VARCHAR(16) NOT NULL, audience_connection_id BIGINT, audience_container_id VARCHAR(255) NOT NULL, audience_thread_root VARCHAR(255), scope_account_generation BIGINT NOT NULL, scope_reader_epoch BIGINT NOT NULL, scope_consent_epoch BIGINT NOT NULL, scope_authority VARCHAR(16) NOT NULL, scope_workspace_id BIGINT, scope_workspace_generation BIGINT, scope_binding_id BIGINT, scope_binding_generation BIGINT, scope_native_actor_id VARCHAR(255), opened_at TIMESTAMP(6) WITH TIME ZONE NOT NULL, deadline TIMESTAMP(6) WITH TIME ZONE NOT NULL, -- One request per source: a source has one account, so the pair is unique where the source is. CONSTRAINT uk_mentor_request_source UNIQUE (account_id, source_id), CONSTRAINT uk_mentor_request_owner UNIQUE (account_id, id), CONSTRAINT sfk_mentor_request_source FOREIGN KEY (account_id, source_id) REFERENCES public.mentor_source (account_id, id), CONSTRAINT ck_mentor_request_state CHECK (state IN ('OPEN', 'RUNNING', 'ANSWERED', 'CONTINUED', 'FAILED', 'STOPPED', 'SUPERSEDED', 'EXPIRED')), CONSTRAINT ck_mentor_request_audience_transport CHECK (audience_transport IN ('SLACK', 'APP')) ); CREATE TABLE public.mentor_event ( id UUID NOT NULL CONSTRAINT mentor_eventPK PRIMARY KEY, account_id BIGINT NOT NULL, binding_id BIGINT NOT NULL, native_event_id VARCHAR(255) NOT NULL, kind VARCHAR(32) NOT NULL, source_id UUID NOT NULL, request_id UUID, disposition VARCHAR(16) NOT NULL, reason VARCHAR(32), source_ref VARCHAR(64) NOT NULL, occurred_at TIMESTAMP(6) WITH TIME ZONE NOT NULL, received_at TIMESTAMP(6) WITH TIME ZONE NOT NULL, CONSTRAINT uk_mentor_event_key UNIQUE (binding_id, native_event_id), CONSTRAINT sfk_mentor_event_source FOREIGN KEY (account_id, source_id) REFERENCES public.mentor_source (account_id, id), CONSTRAINT sfk_mentor_event_request FOREIGN KEY (account_id, request_id) REFERENCES public.mentor_request (account_id, id), CONSTRAINT ck_mentor_event_kind CHECK (kind IN ('MESSAGE', 'MESSAGE_EDITED', 'MESSAGE_DELETED', 'CONTROL_STOP')), CONSTRAINT ck_mentor_event_disposition CHECK (disposition IN ('OPENED', 'REVISED', 'FENCED', 'RECORDED')), CONSTRAINT ck_mentor_event_reason CHECK (reason IN ('UNAUTHORIZED', 'AUTHOR_MISMATCH', 'ALREADY_OPENED', 'NO_REQUEST', 'STALE_REVISION', 'SOURCE_DELETED', 'REQUEST_SETTLED', 'STOP_NOT_HANDLED')) ); CREATE INDEX idx_mentor_event_source ON public.mentor_event (account_id, source_id); CREATE INDEX idx_mentor_event_request ON public.mentor_event (account_id, request_id);
ALTER TABLE public.mentor_source ENABLE ROW LEVEL SECURITY; CREATE POLICY mentor_source_owner ON public.mentor_source TO hephaestus_app USING (account_id = public.current_owner_account()) WITH CHECK (account_id = public.current_owner_account()); ALTER TABLE public.mentor_request ENABLE ROW LEVEL SECURITY; CREATE POLICY mentor_request_owner ON public.mentor_request TO hephaestus_app USING (account_id = public.current_owner_account()) WITH CHECK (account_id = public.current_owner_account()); ALTER TABLE public.mentor_event ENABLE ROW LEVEL SECURITY; CREATE POLICY mentor_event_owner ON public.mentor_event TO hephaestus_app USING (account_id = public.current_owner_account()) WITH CHECK (account_id = public.current_owner_account());
-- The owner of one canonical message, before any owner is bound: the intake binds it for an edit or a delete. CREATE FUNCTION public.mentor_source_owner(binding bigint, container text, message text) RETURNS bigint LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$ SELECT account_id FROM public.mentor_source WHERE binding_id = $1 AND container_id = $2 AND native_message_id = $3 $$; ALTER FUNCTION public.mentor_source_owner(bigint, text, text) OWNER TO hephaestus_owner; REVOKE ALL ON FUNCTION public.mentor_source_owner(bigint, text, text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.mentor_source_owner(bigint, text, text) TO hephaestus_app;
-- A workspace purge and a Slack disconnect erase every account's mentor rows of that workspace. The sources are -- locked first, the order that intake takes, so an admission in flight finishes first or fails its NOWAIT lock. CREATE FUNCTION public.mentor_erase_workspace(workspace bigint) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$ DECLARE erased integer; BEGIN PERFORM 1 FROM public.mentor_source WHERE workspace_id = $1 ORDER BY id FOR UPDATE; DELETE FROM public.mentor_event e USING public.mentor_source s WHERE e.source_id = s.id AND s.workspace_id = $1; DELETE FROM public.mentor_request r USING public.mentor_source s WHERE r.source_id = s.id AND s.workspace_id = $1; DELETE FROM public.mentor_source WHERE workspace_id = $1; GET DIAGNOSTICS erased = ROW_COUNT; RETURN erased; END $$; ALTER FUNCTION public.mentor_erase_workspace(bigint) OWNER TO hephaestus_owner; REVOKE ALL ON FUNCTION public.mentor_erase_workspace(bigint) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.mentor_erase_workspace(bigint) TO hephaestus_app;
